Let me run it.{"action": "run_sql", "sql": "WITH RECURSIVE cur AS (SELECT id, set_num FROM inventories i WHERE version = (SELECT MAX(version) FROM inventories i2 WHERE i2.set_num = i.set_num)), items AS (SELECT '71837-1' AS item, 1 AS qty UNION ALL SELECT edges.child, items.qty * edges.mult FROM items JOIN (SELECT cur.set_num AS parent, iset.set_num AS child, iset.quantity AS mult FROM cur JOIN inventory_sets iset ON iset.inventory_id = cur.id UNION ALL SELECT cur.set_num AS parent, im.fig_num AS child, im.quantity AS mult FROM cur JOIN inventory_minifigs im ON im.inventory_id = cur.id) edges ON edges.parent = items.item), item_parts AS (SELECT items.item, items.qty, ip.quantity AS pq FROM items JOIN cur ON cur.set_num = items.item JOIN inventory_parts ip ON ip.inventory_id = cur.id AND ip.is_spare = false), direct AS (SELECT COALESCE(SUM(ip.quantity),0) AS q FROM cur JOIN inventory_parts ip ON ip.inventory_id = cur.id WHERE cur.set_num = '71837-1' AND ip.is_spare = false), total AS (SELECT COALESCE(SUM(qty * pq),0) AS t FROM item_parts) SELECT direct.q AS direct_qty, total.t AS total_qty, ROUND((total.t - direct.q) * 100.0 / total.t, 2) AS pct_nested FROM direct, total"}

